import json
C=[]
def c(id,t,sub,u,era,la,en,teach,ctx,img,wiki,src=None,conf=None,vocab=(),gram=()):
    d=dict(id=id,type=t,subtype=sub,unit=u,era=era,latin=la,translation=en,teaches=teach,context=ctx,
      vocab_ids=list(vocab),grammar_tags=list(gram),
      image_idea=dict(zip(["description","kind","candidate_source","license_status"],img)),
      learn_more=dict(label=wiki.replace("_"," ")+" (Wikipedia)",url="https://en.wikipedia.org/wiki/"+wiki))
    if src: d["source"]=dict(zip(["work","citation"],src)); d["attribution_confidence"]=conf or "verified"
    else: d["attribution_note"]="Constructed teaching sentence (not a quotation)."
    C.append(d)
WC="Wikimedia Commons"; PD="PD-art likely; verify file page"; CC0="CC0 (Met Open Access); verify object page"
# UNIT 1 Roma
c("v-urbs","vocab","vocab",1,"republic","urbs, urbis f.","city","DCC core noun; Rome is simply Urbs","Romans called Rome just 'the City'. Popes still bless 'urbī et orbī' — to the City and the world. English 'urban', 'suburb' come from it.",("Model of ancient Rome (Museo della Civiltà Romana), wide crop",'building',WC,PD),"Plastico_di_Roma_antica",vocab=["urbs"])
c("v-via","vocab","vocab",1,"republic","via, viae f.","road, way","1st-declension model noun","The Via Appia, begun 312 BC by Appius Claudius, ran from Rome to Capua and later Brundisium. Its paving stones are still walkable today.",("Via Appia paving with tombs, portrait crop",'building',WC,"CC BY-SA likely; verify"),"Appian_Way",vocab=["via"])
c("g-sum-est","grammar","grammar",1,"republic","Rōma urbs est. Via longa est.","Rome is a city. The road is long.","sum/est; verb-final word order","Latin usually puts the verb last, but 'est' can float. Start every sentence by finding the verb, then its subject in the nominative.",("Cut-out Capitoline Wolf",'statue_cutout',WC,PD),"Capitoline_Wolf",gram=["sum","nominative","word_order"])
c("g-1decl-nom","grammar","grammar",1,"regal","Lupa, puella, rēgīna, Rōma","she-wolf, girl, queen, Rome","1st declension nominative singular -a, mostly feminine","Most -a nouns are feminine. Legend says a lupa nursed Romulus and Remus; 'lupa' was also slang for a prostitute, which ancient writers used to rationalise the myth.",("Capitoline Wolf bronze cut-out",'statue_cutout',WC,PD),"First_declension",gram=["1st_decl","nominative"])
c("i-spqr","artifact","inscription",1,"republic","S·P·Q·R — Senātus Populusque Rōmānus","The Senate and the Roman People","Abbreviations; enclitic -que = 'and'","The formula named the Roman state on coins, arches and standards. Rome's manhole covers still carry it. Note -que glued to the second word: populus-que.",("Modern Rome manhole cover with SPQR or Arch of Titus attic",'inscription',WC,"CC BY-SA likely; verify"),"SPQR",gram=["enclitic_que","abbreviations"])
c("x-map-roma","place","mix:map",1,"regal","Septem montēs: Palātium, Capitōlium, Aventīnus…","The seven hills: Palatine, Capitoline, Aventine…","Place names in the nominative; map-tap game","Tap each hill as you hear its Latin name. The Palatine gave English 'palace', because emperors built their homes there.",("Public-domain map of the seven hills of Rome",'painting',WC,PD),"Seven_hills_of_Rome")
# UNIT 2 Familia
c("v-pater","vocab","vocab",2,"republic","pater, patris m.; māter, mātris f.","father; mother","Core family nouns (DCC top 200)","The paterfamilias held legal power (patria potestās) over his household, even adult sons. Mothers like Cornelia shaped sons' education and reputation.",("Roman funerary relief of a married couple (Met)",'artifact',"Met Open Access",CC0),"Pater_familias",vocab=["pater","mater"])
c("v-filius","vocab","vocab",2,"republic","fīlius, -ī m.; fīlia, -ae f.","son; daughter","2nd vs 1st declension pairs","Roman names showed descent: 'M. F.' on inscriptions means Mārcī fīlius, son of Marcus. Compare Agrippa's L·F on the Pantheon.",("Funerary stele with family portrait (Met)",'artifact',"Met Open Access",CC0),"Roman_naming_conventions",vocab=["filius","filia"])
c("g-acc","grammar","grammar",2,"republic","Pater fīlium amat. Fīlium pater amat.","The father loves the son. (same meaning)","Accusative marks the object, so word order is free","Endings, not position, show who does what: -um/-am object, -us/-a subject. Swap word order and the meaning stays.",("Relief of father and child",'artifact',"Met Open Access",CC0),"Accusative_case",gram=["accusative","word_order"])
c("g-2decl","grammar","grammar",2,"republic","servus, servum; puer; dōnum","slave; boy; gift","2nd declension masc. -us/-um and neuter -um","Enslaved people (servī) were part of the familia. Neuter nouns like dōnum look the same as subject and object.",("Mosaic of servants serving a banquet (Bardo/Commons)",'artifact',WC,PD),"Second_declension",gram=["2nd_decl"])
c("d-familia","vocab","derivative",2,"republic","familia, domus → family, domestic, domicile, paternal, maternal","household, home","Derivatives as memory hooks","A Roman familia meant the whole household, slaves included. Domus gives 'domestic' and 'dome'; pater gives 'paternal', 'patron', 'patriot'.",("House of the Vettii atrium, Pompeii",'building',WC,"CC BY-SA likely; verify"),"Domus",vocab=["familia","domus","pater"])
c("l-bulla","artifact","daily_life",2,"republic","bulla aurea","golden amulet","Daily life vocab; 1st decl. noun + adjective agreement","Freeborn Roman boys wore a bulla amulet until about age 16, when they dedicated it to the household gods (Larēs) and put on the adult toga.",("Etruscan/Roman gold bulla, cut-out (Met or Walters)",'artifact',"Met Open Access / Walters",CC0),"Bulla_(amulet)")
c("x-whosays-cornelia","person","mix:who_said_it",2,"republic","Haec ornāmenta sunt mea. — Cornēlia? Līvia? Lucrētia?","These are my jewels — who said it?","Recall of quote card; demonstratives haec","Pick the speaker. Answer: Cornelia, mother of the Gracchi, per Valerius Maximus 4.4 pr. Links to existing card in rome-cards.json.",("Cornelia painting (Angelica Kauffman) cut to arch",'painting',WC,PD),"Cornelia_(mother_of_the_Gracchi)",src=("Valerius Maximus, Facta et dicta memorabilia","4.4 praef."))
# UNIT 3 Legio
c("v-miles","vocab","vocab",3,"empire","mīles, mīlitis m.","soldier","Core noun; preview of 3rd-decl. stem change","A legionary served about 25 years under Augustus' reforms. English 'military', 'militia' keep the stem mīlit-.",("Cut-out legionary statue or tombstone relief",'statue_cutout',WC,PD),"Roman_legion",vocab=["miles"])
c("v-castra","vocab","vocab",3,"empire","castra, -ōrum n. pl.","army camp","Plural-only noun","Every night on campaign a legion dug a fortified camp. Place names ending -chester, -caster, -cester (Lancaster, Chester) descend from castra.",("Housesteads fort, Hadrian's Wall, aerial",'building',WC,"CC BY-SA; verify"),"Castra",vocab=["castra"])
c("g-1conj","grammar","grammar",3,"empire","Mīlitēs ambulant. Legiō pugnat.","The soldiers march. The legion fights.","1st conjugation present: -ō, -ās, -at, -āmus, -ātis, -ant","Chant the endings like a marching cadence. Plural -nt vs singular -t tells you how many are acting.",("Trajan's Column marching relief",'artifact',WC,PD),"Latin_conjugation",gram=["1st_conj","present","plural"])
c("g-2conj","grammar","grammar",3,"empire","Centuriō mīlitēs videt et monet.","The centurion sees and warns the soldiers.","2nd conjugation present (videō, moneō)","Centurions led roughly 80 men and carried a vine-stick (vītis) as a badge of rank. Their tombstones often show it.",("Tombstone of centurion M. Caelius (Bonn), portrait",'artifact',WC,PD),"Centurion",gram=["2nd_conj","present"])
c("i-vindolanda","artifact","inscription",3,"empire","…ut libentius diem sōllemnem…agās…","…so that you may more gladly spend the birthday…","Real handwriting from a fort; letter formulae","Claudia Severa invited Sulpicia Lepidina to her birthday about AD 100: the earliest known Latin handwriting by a woman, found at Vindolanda.",("Vindolanda tablet 291 photo (British Museum)",'manuscript',"British Museum / Commons","BM licence varies; verify"),"Vindolanda_tablets",src=("Tabulae Vindolandenses","Tab. Vindol. II 291"),conf="verified")
c("l-pila","artifact","daily_life",3,"republic","pīlum, -ī n.","javelin","Army vocab; neuter 2nd decl.","Legionaries threw the pilum before closing in. Its soft iron shank bent on impact so enemies could not throw it back, according to Caesar-era practice and archaeology.",("Reconstructed pilum or Roman sword, cut-out",'artifact',WC,"verify"),"Pilum")
c("x-parse-signum","artifact","mix:parse",3,"empire","LEG XX V V","Legiō vīcēsima Valeria Victrīx","Parse-the-inscription: unpack numerals and abbreviations","Tap each chunk to expand it. Legion XX served in Britain; its boar emblem appears on stamped tiles and building stones from Chester and Hadrian's Wall.",("Legio XX building stone (Commons)",'inscription',WC,"verify"),"Legio_XX_Valeria_Victrix",gram=["abbreviations","roman_numerals"])
# UNIT 4 Forum
c("v-res-publica","vocab","vocab",4,"republic","rēs pūblica, reī pūblicae f.","the state, commonwealth","Noun + adjective agreement","Literally 'the public thing'. English 'republic' comes straight from it; Cicero wrote a dialogue titled Dē rē pūblicā.",("Roman Forum view from Capitoline",'building',WC,"CC BY-SA; verify"),"Roman_Republic",vocab=["res","publicus"])
c("v-senatus","vocab","vocab",4,"republic","senātus, -ūs m.; cōnsul, -is m.","senate; consul","Political core vocab","'Senātus' comes from senex, old man: a council of elders. Two consuls were elected yearly, and years were named after them.",("Curia Julia exterior",'building',WC,"CC BY-SA; verify"),"Roman_Senate",vocab=["senatus","consul"])
c("g-gen","grammar","grammar",4,"republic","Forum Rōmānōrum; Templum Sāturnī","the Forum of the Romans; the Temple of Saturn","Genitive = 'of'","Saturn's temple held the state treasury (aerārium). Its eight columns still stand at the Forum's west end.",("Temple of Saturn columns, portrait crop",'building',WC,"verify"),"Temple_of_Saturn",gram=["genitive"])
c("g-dat","grammar","grammar",4,"republic","Senātus Caesarī honōrēs dat.","The Senate gives honours to Caesar.","Dative = 'to/for'","In 44 BC the Senate heaped honours on Caesar, including dictator for life. Weeks later senators killed him in the Curia of Pompey.",("Death of Caesar, Gérôme (painting)",'painting',WC,PD),"Assassination_of_Julius_Caesar",gram=["dative"])
c("g-adj","grammar","grammar",4,"republic","vir bonus, fēmina bona, templum bonum","good man, good woman, good temple","1st/2nd decl. adjective agreement","Adjectives copy their noun's gender, number and case. Cato defined the orator as vir bonus dīcendī perītus — a good man skilled in speaking (via Quintilian 12.1.1).",("Cut-out bust of Cato-type Roman elder",'statue_cutout',"Met Open Access",CC0),"Latin_declension",gram=["adjectives","agreement"],src=("Quintilian, Institutio Oratoria (quoting Cato)","12.1.1"))
c("l-toga","artifact","daily_life",4,"republic","toga, -ae f.","toga","Daily life; 1st decl.","Only citizens could wear the toga. Candidates for office whitened theirs with chalk (toga candida), giving English 'candidate'.",("Togatus statue cut-out",'statue_cutout',WC,PD),"Toga",vocab=["toga"])
c("d-dico","vocab","derivative",4,"republic","dīcō, dīcere, dīxī, dictum → dictate, diction, verdict, predict","say","Principal parts unlock derivatives","Root dict- runs through law and rhetoric: a dictator was one whose word was law. Cicero's speeches made dīcere the orator's verb.",("Cicero Denounces Catiline, Maccari fresco",'painting',WC,PD),"Cicero",vocab=["dico"])
# UNIT 5 Gods
c("v-deus","vocab","vocab",5,"republic","deus, -ī m.; dea, -ae f.","god; goddess","Core vocab; irregular plural dī","Romans honoured many gods; deī and dī are both plural forms. English 'deity', 'divine' (from dīvus) come from this family.",("Cut-out marble Jupiter or Minerva (Met)",'statue_cutout',"Met Open Access",CC0),"Roman_mythology",vocab=["deus","dea"])
c("v-templum","vocab","vocab",5,"empire","templum, -ī n.","temple, sacred space","Neuter 2nd decl.","Originally templum meant a space marked out by augurs for watching birds. English 'contemplate' kept that idea of watching.",("Maison Carrée, Nîmes",'building',WC,"verify"),"Roman_temple",vocab=["templum"])
c("g-3decl","grammar","grammar",5,"republic","rēx, rēgis; lēx, lēgis; pāx, pācis","king, law, peace","3rd declension: learn the genitive to find the stem","The nominative hides the stem; the genitive reveals it. Rome expelled its kings (rēgēs) traditionally in 509 BC and hated the word rēx afterward.",("Ara Pacis Augustae relief",'artifact',WC,"verify"),"Third_declension",gram=["3rd_decl"])
c("g-abl-prep","grammar","grammar",5,"empire","in templō, cum deīs, ex urbe","in the temple, with the gods, out of the city","Prepositions + ablative (in, cum, ex/ē, ā/ab, dē, sine)","Mnemonic: SID & CAPPE. The fire of Vesta burned in aede Vestae, guarded by six Vestal Virgins.",("Temple of Vesta, Roman Forum",'building',WC,"verify"),"Temple_of_Vesta",gram=["ablative","prepositions"])
c("i-pantheon-parse","artifact","mix:parse",5,"empire","M·AGRIPPA·L·F·COS·TERTIVM·FECIT","Marcus Agrippa, son of Lucius, consul for the third time, made this","Parse-the-inscription game built on existing card i-pantheon-agrippa","Drag each abbreviation to its full form. Reuses CIL VI 896 already verified-pending in rome-cards; here it tests abbreviations and the perfect fēcit as a preview.",("Pantheon portico inscription close-up",'inscription',WC,"verify"),"Pantheon,_Rome",src=("Pantheon inscription","CIL VI 896"))
c("l-lares","artifact","daily_life",5,"empire","larārium; Larēs et Penātēs","household shrine; household gods","Religion at home; 3rd decl. plurals","Every house had a lararium where the family offered food and wine to the Lares. Painted lararia survive at Pompeii, often with a snake guardian.",("Lararium, House of the Vettii, Pompeii",'building',WC,"verify"),"Lares")
# UNIT 6 Empire
c("v-imperator","vocab","vocab",6,"empire","imperātor, -ōris m.; imperium, -ī n.","commander; power to command","Core vocab; derivatives emperor, imperial","Imperātor was a title soldiers shouted for a victorious general. Augustus turned it into a permanent name, giving us 'emperor'.",("Augustus of Prima Porta cut-out",'statue_cutout',WC,PD),"Augustus_of_Prima_Porta",vocab=["imperator","imperium"])
c("g-perf-rg","grammar","grammar",6,"empire","Bella terrā et marī cīvīlia externaque tōtō in orbe terrārum saepe gessī.","I often waged wars, civil and foreign, on land and sea throughout the whole world.","Perfect tense first-person -ī (gessī)","Augustus' own account of his deeds was inscribed on bronze pillars at his mausoleum. The best copy survives in Ankara.",("Res Gestae wall at Ankara (Monumentum Ancyranum)",'inscription',WC,"verify"),"Res_Gestae_Divi_Augusti",src=("Res Gestae Divi Augusti","3.1"),gram=["perfect"])
c("g-impf","grammar","grammar",6,"empire","Rōma latericiam accēpī, marmoream relīquī (Suet. Aug. 28) / imperfect: Rōmānī lateribus aedificābant.","I found Rome (made) of brick and left it (made) of marble. / The Romans used to build with bricks.","Perfect vs imperfect (-bā-) contrast","Suetonius reports Augustus' boast; the imperfect describes ongoing past habit, the perfect completed acts.",("Forum of Augustus remains",'building',WC,"verify"),"Forum_of_Augustus",src=("Suetonius, Divus Augustus","28.3"),gram=["imperfect","perfect"])
c("g-possum","grammar","grammar",6,"empire","possum, potes, potest… + infinitive","I can, you can, s/he can","possum = pot + sum","Learn sum first, then glue pot- on (pos- before s). Pairs with an infinitive: venīre possum, I can come.",("Coin of Augustus (Met/ANS)",'coin',"Met Open Access",CC0),"Latin_grammar",gram=["possum"])
c("i-coin-divi-f","artifact","coin",6,"empire","CAESAR DIVI F","Caesar, son of the deified (Julius)","Coin legend reading; genitive + abbreviation","Octavian stressed his adoption by the deified Julius on coins. DIVI F = dīvī fīlius, a powerful propaganda line before the name Augustus (27 BC).",("Denarius of Octavian, CAESAR DIVI F (ANS/Met)",'coin',"Met Open Access / ANS",CC0),"Augustus",gram=["genitive","abbreviations"])
c("l-denarius","artifact","daily_life",6,"empire","dēnārius, as, sēstertius","denarius, as, sestertius (coins)","Money vocab; numerals","A denarius was worth four sesterces. 'Dēnārius' (from dēnī, ten each) gave the 'd' in old British £sd and the word 'dinar'.",("Silver denarius obverse and reverse",'coin',"Met Open Access",CC0),"Denarius")
c("x-timeline-emp","person","mix:timeline",6,"empire","Augustus, Tiberius, Claudius, Nerō, Trāiānus, Hadriānus","emperors in order","Ordering game with nominative names and dates","Drag emperors onto the timeline. Trajan's conquests brought the empire to its largest extent in AD 117.",("Cut-out busts from Met/Commons, one per emperor",'statue_cutout',"Met Open Access",CC0),"List_of_Roman_emperors")
# UNIT 7 Poets
c("v-amo","vocab","vocab",7,"republic","amō, amāre, amāvī, amātum","love","Model 1st conjugation verb with principal parts","Catullus' poems to 'Lesbia' made amō the poet's verb. Its parts are the pattern for all regular 1st-conjugation verbs.",("Fresco of a couple, Pompeii (Terentius Neo)",'painting',WC,PD),"Catullus",vocab=["amo"])
c("g-imperative","grammar","grammar",7,"republic","Carpe diem, quam minimum crēdula posterō.","Pluck the day, trusting as little as possible in tomorrow.","Imperative singular (carpe); first sighting","Horace ends an ode to Leuconoe with this line: harvest today like ripe fruit. Imperatives: stem alone (amā, vidē, carpe), plural -te.",("Horace manuscript or Horace portrait medallion",'manuscript',WC,PD),"Carpe_diem",src=("Horace, Odes","1.11.8"),gram=["imperative"])
c("g-future","grammar","grammar",7,"empire","Nōn omnis moriar.","I shall not wholly die.","Future of 3rd conjugation (-ar/-ēs/-et)","Horace closes Odes 3 confident his poetry will outlive him. Links to the existing 'Exēgī monumentum' card.",("Horace bust or Odes incunable",'manuscript',WC,PD),"Odes_(Horace)",src=("Horace, Odes","3.30.6"),gram=["future"])
c("g-pronoun","grammar","grammar",7,"republic","Ego, tū; mē, tē; mihi, tibi","I, you; me, you; to me, to you","Personal pronouns","Poetry is full of ego and tū. Ovid's lover tells his girl to come to him: personal pronouns carry the drama of address.",("Ovid portrait or statue at Constanța",'statue_cutout',WC,"verify"),"Latin_personal_pronouns",gram=["pronouns"])
c("v-tempus","vocab","vocab",7,"empire","tempus, temporis n.","time","3rd-decl. neuter; ties to 3 existing quotes","Virgil's 'fugit irreparābile tempus' and Ovid's 'tempus edāx rērum' both use it. English 'temporary', 'contemporary', 'tempo'.",("Roman sundial (Met)",'artifact',"Met Open Access",CC0),"Roman_timekeeping",vocab=["tempus"])
c("x-meter","quote","mix:listen",7,"empire","Arma virumque canō…","I sing of arms and the man…","Hear dactylic hexameter: long/short tap rhythm","Tap along to a human reading of Aeneid 1.1 in restored pronunciation. Learners feel vowel length, which reinforces macrons.",("Vergilius Romanus folio",'manuscript',WC,PD),"Dactylic_hexameter",src=("Virgil, Aeneid","1.1"))
# UNIT 8 Philosophers
c("v-animus","vocab","vocab",8,"empire","animus, -ī m.; anima, -ae f.","mind, spirit; soul, breath","Close pairs; core vocab","Stoics trained the animus to stay calm. English 'animate', 'animal', 'unanimous' (ūnus + animus).",("Seneca double herm, cut-out",'statue_cutout',WC,PD),"Seneca_the_Younger",vocab=["animus","anima"])
c("g-infinitive","grammar","grammar",8,"empire","Vīvere, mī Lūcīlī, mīlitāre est.","To live, my Lucilius, is to be a soldier.","Infinitive as noun/subject","Seneca compares life to military service in his letters to Lucilius. Infinitives end -re and can act as nouns.",("Seneca bust",'statue_cutout',WC,PD),"Epistulae_Morales_ad_Lucilium",src=("Seneca, Epistulae Morales","96.5"),gram=["infinitive"])
c("g-ind-stat","grammar","grammar",8,"republic","Dīcunt Rōmulum urbem condidisse.","They say that Romulus founded the city.","Indirect statement: accusative + infinitive","Latin has no word for 'that' here: the subject goes accusative, the verb infinitive. Livy uses this constantly to report legends he doubts.",("Romulus and Remus on Lupa, cut-out",'statue_cutout',WC,PD),"Indirect_speech",gram=["indirect_statement"])
c("d-video","vocab","derivative",8,"empire","videō, vidēre, vīdī, vīsum → video, vision, evident, provide, visa","see","Derivatives from supine stem","Philosophers prized seeing truly. Your 'video' is literally 'I see'; 'provide' is to see ahead.",("Roman fresco eye/portrait of a woman (Sappho fresco)",'painting',WC,PD),"Latin_influence_in_English",vocab=["video"])
c("x-greek-flag","person","mix:true_false",8,"empire","Marcus Aurēlius Latīnē scrīpsit 'Ad sē ipsum'. Vērum an falsum?","Marcus Aurelius wrote 'To Himself' in Latin. True or false?","Comprehension in simple Latin; cultural accuracy","False: the Meditations are in Greek, the language of philosophy for educated Romans. Bilingualism was normal among the elite.",("Equestrian statue of Marcus Aurelius, Capitoline, cut-out",'statue_cutout',WC,"verify"),"Meditations")
c("l-schola","artifact","daily_life",8,"empire","lūdus, magister, tabula, stilus","school, teacher, wax tablet, stylus","School vocab","Roman children learned letters with a grammaticus or lūdī magister, writing on wax tablets with a stylus — whose flat end erased mistakes.",("Roman wax tablet and stylus (Commons/Met)",'artifact',WC,"verify"),"Wax_tablet")
# UNIT 9 Christian Rome & Fall
c("g-passive","grammar","grammar",9,"late_antiquity","Rōma capta est (AD 410).","Rome was captured.","Perfect passive: participle + est","Alaric's Visigoths sacked Rome in 410. The shock prompted Augustine to write the City of God. Present passive: -tur (capitur, 'is captured').",("Sack of Rome painting (Joseph-Noël Sylvestre)",'painting',WC,PD),"Sack_of_Rome_(410)",gram=["passive"])
c("i-chirho","artifact","coin",9,"late_antiquity","☧ (Chī-Rhō) on coins of Constantine; Vulgate: Ego sum α et ω","Chi-Rho; I am Alpha and Omega","Reading Christian symbols on late Roman coins","Constantine adopted the Chi-Rho after 312. Later coins pair it with Alpha and Omega from Revelation (Apoc. 1:8 in the Vulgate).",("Late Roman coin or silver plate with Chi-Rho",'coin',"Met Open Access",CC0),"Chi_Rho",src=("Vulgate, Apocalypsis","1:8"))
c("v-rex","vocab","vocab",9,"late_antiquity","rēx, rēgis m.; rēgnum, -ī n.","king; kingdom","Core vocab revisited in a new era","After 476 Germanic kings ruled the West in Latin. Odoacer deposed Romulus Augustulus; Theodoric ruled Italy as rēx.",("Mausoleum of Theodoric, Ravenna",'building',WC,"verify"),"Odoacer",vocab=["rex","regnum"])
c("x-vulgate","quote","mix:fill_blank",9,"late_antiquity","Ego sum via, et vēritās, et vīta.","I am the way, and the truth, and the life.","Fill-in-the-blank with units 1–5 vocab (via, sum)","Jerome's Vulgate (c. 382–405) became the West's Bible for a millennium. Its plain Latin is ideal reading for beginners.",("Codex Amiatinus Ezra page",'manuscript',WC,PD),"Vulgate",src=("Vulgate, Ioannes","14:6"),gram=["sum"])
c("d-crux","vocab","derivative",9,"late_antiquity","crux, crucis → crucial, crucify, crusade, excruciating","cross","3rd-decl. stem crūc- in derivatives","Crucifixion was a Roman punishment, abolished by Constantine. 'Excruciating' literally means 'out of the cross'; 'crucial' first meant a crossroads.",("Early Christian cross or ivory panel (Met)",'artifact',"Met Open Access",CC0),"Crucifixion")
c("l-annona","artifact","daily_life",9,"late_antiquity","pānis, frūmentum, annōna","bread, grain, grain supply","Food vocab; 3rd vs 2nd decl.","Rome fed citizens free grain, later bread. Losing Egypt and Africa's grain helped starve the late western capital; Juvenal's 'pānem et circēnsēs' card connects here.",("Carbonised loaf from Pompeii",'artifact',WC,"verify"),"Cura_Annonae")
# UNIT 10 Monks & Manuscripts
c("g-relative","grammar","grammar",10,"early_medieval","Pater noster, quī es in caelīs","Our Father, who art in heaven","Relative pronoun quī/quae/quod","The Lord's Prayer (Matt. 6:9) was the first Latin many medieval people learned. Already in medieval-cards; here it drives a relative-clause drill.",("Carolingian Gospel book page",'manuscript',WC,PD),"Relative_clause",src=("Vulgate, Matthaeus","6:9"),gram=["relative_clause"])
c("v-liber","vocab","vocab",10,"early_medieval","liber, librī m.; legō, legere, lēgī, lēctum","book; read","Core vocab; e-dropping 2nd decl.","Monks copied books in the scriptorium. 'Library', 'lecture', 'legend' (things to be read). Don't confuse liber (book) with līber (free).",("Book of Kells folio",'manuscript',WC,PD),"Scriptorium",vocab=["liber","lego"])
c("l-monasterium","artifact","daily_life",10,"early_medieval","monasterium, abbās, monachus, hōra","monastery, abbot, monk, hour","Monastic vocab; Greek loans in Latin","Benedict's Rule organised the day into hours of prayer and work. 'Monk' and 'abbot' come from Greek and Aramaic through Latin.",("Plan of St Gall (Cod. Sang. 1092)",'manuscript',"e-codices / Commons",PD),"Plan_of_Saint_Gall")
c("i-karolus","artifact","coin",10,"early_medieval","KAROLVS IMP AVG","Charles, Emperor, Augustus","Medieval coin legend reusing Roman titles","Charlemagne, crowned in 800, issued coins styling himself like a Roman emperor. Compare with Augustus' coins in Unit 6.",("Denier of Charlemagne (Commons)",'coin',WC,PD),"Charlemagne",gram=["abbreviations"])
c("x-colophon","artifact","mix:parse",10,"early_medieval","Explicit liber… Ōrāte prō scrīptōre.","Here ends the book… Pray for the scribe.","Parse a scribe's colophon; imperative plural review","Scribes often signed off with a request for prayer or a complaint about cold fingers. 'Explicit' (it is unrolled) ended books; 'incipit' began them.",("Manuscript colophon page (Commons)",'manuscript',WC,PD),"Colophon_(publishing)",gram=["imperative","relative_clause"])
c("x-map-medieval","place","mix:map",10,"early_medieval","Lindisfarna, Iona, Sanctus Gallus, Aquīsgrānum, Rōma","Lindisfarne, Iona, St Gall, Aachen, Rome","Latin place names; map game","Tap where Latin learning survived and spread: Irish and Northumbrian monasteries, St Gall, Charlemagne's court at Aachen.",("Public-domain map of Carolingian Europe",'painting',WC,PD),"Carolingian_Renaissance")
c("d-scribo","vocab","derivative",10,"early_medieval","scrībō, scrībere, scrīpsī, scrīptum → scribe, script, describe, manuscript","write","Derivatives; manū scrīptum = written by hand","A 'manuscript' is literally manū scrīptus, written by hand. Ties to the Scriba rank in the reward ladder.",("Evangelist portrait writing (Ebbo Gospels)",'manuscript',WC,PD),"Manuscript",vocab=["scribo"])
